import{_ as o,o as t,c as s,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Assets — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Assets — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/assets"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Assets — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/assets"}]]},"headers":[],"relativePath":"deployment/assets.md","filePath":"deployment/assets.md","lastUpdated":1787698998000}'),n={name:"deployment/assets.md"};function i(r,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="assets-—-production-guide" tabindex="-1">Assets — Production Guide <a class="header-anchor" href="#assets-—-production-guide" aria-label="Permalink to &quot;Assets — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>assets</code></li><li>Category: <code>operations</code> (<strong>Operations</strong>), <code>category_sort_order = 40</code></li><li><strong>Free Marketplace opt-in</strong> module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 80</code>, version <strong>1.0.0</strong></li><li><strong>No</strong> hard <code>module_dependencies</code> rows</li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> by default; enable Assets from Marketplace</li><li>Soft optional links to Vendors / Employees are validated only when those modules are entitled</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong> only)</li><li>Operators enable Assets from Marketplace (free / non-billable install activates immediately)</li><li>Tenant permissions include <code>assets.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No stage seeder — status and category are enums on the asset row. Numbering uses <code>assets_number_prefix</code> (default <code>AST-</code>).</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Assets permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><p>On large tenant fleets, run migrate in a maintenance window (or raise PHP <code>max_execution_time</code>). The synchronizer grants missing links only and swallows concurrent <code>role_has_permissions</code> unique races.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>asset_created</code>, <code>asset_updated</code>, <code>asset_deleted</code>, <code>asset_assigned</code>, <code>asset_note_added</code></li><li>Notifications: assignment (mail + database) via <code>AssetAssignedNotification</code></li><li>Tenant mail settings with Central SMTP fallback</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate asset tables (<code>assets</code>, <code>asset_notes</code>, <code>asset_activities</code>)</li><li>Register the <code>assets</code> catalog module (migration, not seeder) as free opt-in under <code>operations</code></li><li>Confirm <code>module:assets</code> + <code>assets.*</code> permissions on target roles</li><li>Deploy frontend (Assets nav item, list/form/detail)</li><li>Smoke: create a <strong>new</strong> workspace → enable Assets from Marketplace → create/edit/assign/note an asset → soft delete/restore; optionally entitle Vendors/Employees and verify soft links</li></ol><h2 id="roadmap-context" tabindex="-1">Roadmap context <a class="header-anchor" href="#roadmap-context" aria-label="Permalink to &quot;Roadmap context&quot;">​</a></h2><p>Assets ships as free Operations Marketplace opt-in <strong>v1.0.0</strong> (shipped). Documents (<strong>1.0.0</strong>, hard Storage dependency) is also shipped — see <a href="/architecture/module-dependencies">module-dependencies.md</a> and <a href="/getting-started/product-roadmap">product-roadmap.md</a>.</p>',16)])])}const u=o(n,[["render",i]]);export{g as __pageData,u as default};
